fn worker(jobs: Chan[Int], out: Chan[Int]) -> Unit:
    loop:
        match recv(jobs):
            Some(n) => send(out, n * n)
            None => break

fn main() -> Unit:
    let jobs = chan[Int](8)
    let out = chan[Int](8)
    spawn worker(jobs, out)
    var i = 1
    while i <= 4:
        send(jobs, i)
        i = i + 1
    close(jobs)
    var got = 0
    while got < 4:
        match recv(out):
            Some(v) => print(v)
            None => break
        got = got + 1

fn make_adder(n: Int) -> (Int) -> Int:
    fn(x: Int) -> Int: x + n

fn main() -> Unit:
    let add10 = make_adder(10)
    print(add10(5))
    print(add10(32))

fn fib(n: Int) -> Int:
    if n < 2:
        return n
    fib(n - 1) + fib(n - 2)

fn main() -> Unit:
    print(fib(20))

fn main() -> Unit:
    var n = 1
    while n <= 15:
        if n % 15 == 0:
            print("FizzBuzz")
        elif n % 3 == 0:
            print("Fizz")
        elif n % 5 == 0:
            print("Buzz")
        else:
            print(n)
        n = n + 1

# Generics let one definition work over any type. They are fully parametric (no bounds) and
# ERASED — a generic fn compiles to a single function; type arguments are always inferred.

fn map[T, U](xs: List[T], f: (T) -> U) -> List[U]:
    var out: List[U] = []
    for x in xs:
        out = push(out, f(x))
    out

fn fold[T, A](xs: List[T], init: A, step: (A, T) -> A) -> A:
    var acc = init
    for x in xs:
        acc = step(acc, x)
    acc

# a generic data structure, used at two different element types
struct Pair[A, B]:
    first: A
    second: B

fn swap[A, B](p: Pair[A, B]) -> Pair[B, A]:
    Pair(p.second, p.first)

fn dbl(n: Int) -> Int:
    n * 2

fn add(a: Int, b: Int) -> Int:
    a + b

fn main() -> Unit:
    let nums = [1, 2, 3, 4]
    print(map(nums, dbl))          # [2, 4, 6, 8]
    print(fold(nums, 0, add))      # 10

    let p = Pair(1, "one")
    let q = swap(p)                # Pair[Str, Int]
    print(q.first)                 # one
    print(q.second)                # 1

fn checked_div(a: Int, b: Int) -> Result[Int, Str]:
    if b == 0:
        Err("divide by zero")
    else:
        Ok(a / b)

fn compute(a: Int, b: Int, c: Int) -> Result[Int, Str]:
    let x = checked_div(a, b)?
    let y = checked_div(x, c)?
    Ok(y)

fn main() -> Unit:
    print(compute(100, 5, 2))
    print(compute(100, 0, 2))

struct WC:
    word: Str
    count: Int

fn bump(acc: List[WC], w: Str) -> List[WC]:
    var out: List[WC] = []
    var found = false
    for e in acc:
        if e.word == w:
            out = push(out, WC(e.word, e.count + 1))
            found = true
        else:
            out = push(out, e)
    if found:
        out
    else:
        push(out, WC(w, 1))

fn main() -> Unit:
    let words = split("the cat the dog the cat", " ")
    var acc: List[WC] = []
    for w in words:
        acc = bump(acc, w)
    for e in acc:
        print(e.word + ": " + str(e.count))
